import json,copy,numpy as np
from gri_bench.api import load_instance,Experiment
I=load_instance(); E=Experiment(I,seeds=[6111003,6111004,7111002,8111002])
base=json.load(open('candidate.json')); results={}
for scale in [.93,1.0,1.05]:
 d=copy.deepcopy(base); d['parameters']['theta_a']*=scale
 m=E.evaluate(d); rows=m['rows']; key=str(scale)
 results[key]={'design':d,'mean_tir':m['mean_tir'],'minimum_glucose':m['minimum_glucose'],'max_tbr70':m['max_trajectory_tbr70'],'max_tbr54':m['max_trajectory_tbr54'],'feasible':m['feasible'],'patient_means':{},'rows':rows}
 for p in I['patients']:
  rr=[r for r in rows if r['patient']==p]; results[key]['patient_means'][p]=np.mean([r['metrics']['tir'] for r in rr])
 print(key,json.dumps({k:v for k,v in results[key].items() if k not in ('rows','design')}),flush=True)
json.dump(results,open('validation.json','w'),indent=2)
PY
python validate.py", "timeout_seconds": 80}

